INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 8, "トゥインクルウィッシュ", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 155, 16, 100101, "A", "人助け、応援", 44, "人助けが大好き！　前向き格闘娘", "東山奈央", 2, 27, "ヒヨリ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 4, "トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 158, 17, 100201, "O", "料理、人間観察", 47, "戦闘のサポートが得意な、心優しい少女", "種田梨沙", 2, 5, "ユイ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 1, "トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 163, 18, 100301, "B", "読書、乗馬、お茶", 46, "クールで何事にも真っ直ぐな剣士", "早見沙織", 2, 12, "レイ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 8, "リトルリリカル", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 128, 9, 100401, "O", "いたずら、探検", 27, "探検好きのイタズラっ子", "諸星すみれ", 5, 10, "ミソギ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 11, "王宮騎士団（NIGHTMARE）", "？？？", 146, 12, 100501, "O", "ヒーローごっこ", 40, "ヒーローに憧れる騎士見習いの少女", "下田麻美", 8, 25, "マツリ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 11, "悪魔偽王国軍（ディアボロス）", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 150, 13, 100601, "O", "サックス", 42, "甘え上手なみんなの人気者", "浅倉杏美", 7, 22, "アカリ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 1, "悪魔偽王国軍（ディアボロス）", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 130, 14, 100701, "B", "プリンを食べること", 32, "プリン大好きゴースト娘", "雨宮天", 7, 23, "ミヤコ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 10, "ヴァイスフリューゲル　ランドソル支部", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 150, 14, 100801, "AB", "鏡で自分を見ること", 40, "ボクは誰よりも美しい", "大空直美", 15, 10, "ユキ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 7, "トワイライトキャラバン", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 159, 17, 100901, "A", "小説執筆", 45, "前世を信じる中二病患者、「疾風の冥姫」", "髙野麻美", 13, 5, "アンナ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 9, "自警団（カォン）", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 155, 16, 101001, "O", "空想、ぬいぐるみ集め", 42, "マホマホ王国のプリンセス", "内田真礼", 10, 22, "マホ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 8, "ラビリンス", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 156, 15, 101101, "A", "お裁縫", 44, "人懐っこくてマシンガントークな妹系少女", "阿澄佳奈", 3, 25, "リノ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 12, "フォレスティエ", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 156, 17, 101201, "A", "妹と遊ぶこと、二度寝、昼寝、早寝", 46, "みんなのために超能力を使う眠り姫", "大橋彩香", 6, 24, "ハツネ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 8, "トワイライトキャラバン", "", 166, 18, 101301, "O", "読書、魔法", 55, "オタク全開な魔法少女", "佳村はるか", 13, 21, "ナナカ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 11, "自警団（カォン）", "test", 152, 15, 101401, "AB", "読書、推理", 41, "頭脳明晰な美少女名探偵", "水瀬いのり", 10, 3, "カスミ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 9, "フォレスティエ", "test", 165, 21, 101501, "O", "絵本作り", 54, "母性溢れる優しいみんなの「ミサト先生」", "國府田マリ子", 6, 5, "ミサト");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 4, "ルーセント学院", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 167, 17, 101601, "O", "ファッション", 48, "天真爛漫で人気者のカリスマモデル", "上坂すみれ", 14, 10, "スズナ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 7, "自警団（カォン）", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 158, 17, 101701, "A", "踊り、空手", 53, "いつでも「なんくるないさ～」な天然娘", "高森奈津美", 10, 7, "カオリ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 8, "ルーセント学院", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 162, 23, 101801, "B", "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 52, "多くの男性を魅了する無垢な女教師", "伊藤静", 14, 14, "イオ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 4, "リトルリリカル", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 117, 10, 102001, "O", "かわいいもの集め", 21, "お歌もにんじんも、ウサギさんも大好き♪", "日高里菜", 5, 3, "ミミ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 6, "サレンディア救護院", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 150, 12, 102101, "B", "観劇、おままごと", 40, "泣き虫で臆病な守ってあげたい女の子", "植田佳奈", 9, 9, "クルミ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 11, "悪魔偽王国軍（ディアボロス）", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 150, 13, 102201, "O", "ゲーム全般", 40, "人見知りであまのじゃくな女の子", "原紗友里", 7, 22, "ヨリ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 5, "サレンディア救護院", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 148, 14, 102301, "B", "屋内でできる遊び", 38, "ぷうきちといつも一緒！", "芹澤優", 9, 10, "アヤネ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 12, "サレンディア救護院", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 154, 15, 102501, "O", "ご奉仕", 43, "お嬢さまのためにがんばるドジっ娘メイド", "悠木碧", 9, 12, "スズメ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 1, "牧場（エリザベスパーク）", "test", 144, 17, 102601, "B", "あんパン", 42, "遊びと睡眠が何より大事なぐうたら娘", "小岩井ことり", 11, 1, "リン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 7, "トワイライトキャラバン", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 154, 16, 102701, "B", "実験、裁縫、料理", 43, "運命の相手に一途すぎる乙女", "橋本ちなみ", 13, 30, "エリコ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 10, "サレンディア救護院", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 156, 17, 102801, "A", "経営、お茶会", 43, "救護院を経営する優しい庶民派お嬢様", "堀江由衣", 9, 4, "サレン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 1, "カルミナ", "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", 157, 17, 102901, "B", "舞台鑑賞、ダンス", 40, "歌って踊れる大人気アイドル", "日笠陽子", 4, 24, "ノゾミ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 8, "ヴァイスフリューゲル　ランドソル支部", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 163, 16, 103001, "O", "忍法開発", 51, "トーゴクの神秘、オシエテクダサイ！", "佐藤聡美", 15, 31, "ニノン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 12, "悪魔偽王国軍（ディアボロス）", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 157, 18, 103101, "AB", "占い", 42, "占いが得意な霊能少女", "大坪由佳", 7, 22, "シノブ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 3, "メルクリウス財団", "この私とともにいる限り、\nお金に不自由はさせませんわ！", 157, 18, 103201, "AB", "慈善事業", 45, "一人前の商人を目指すパワフルお嬢様", "松嵜麗", 12, 12, "アキノ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 3, "牧場（エリザベスパーク）", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 142, 20, 103301, "B", "漫才", 35, "みんなを笑顔にするお笑い牧場主", "新田恵海", 11, 3, "マヒル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 3, "メルクリウス財団", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 164, 22, 103401, "A", "ウインドーショッピング", 55, "純情でほっとけない大人の女性", "今井麻美", 12, 16, "ユカリ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 2, "リトルリリカル", "test", 118, 8, 103601, "A", "お勉強", 21, "礼儀正しくしっかり者のちびっ子優等生", "小倉唯", 5, 2, "キョウカ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 8, "王宮騎士団（NIGHTMARE）", "test", 149, 13, 103701, "A", "剣術、年長者をからかう", 43, "義理堅くてからかい好きな剣術少女", "茅原実里", 8, 11, "トモ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 11, "牧場（エリザベスパーク）", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 153, 14, 103801, "A", "読書、お散歩", 40, "読書が趣味の病弱少女", "小清水亜美", 11, 3, "シオリ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 6, "フォレスティエ", "友達ができるその日まで…\nBB団で\nトレーニングですっ！", 158, 13, 104001, "AB", "友達作りのイメトレ", 44, "「友達」に憧れる、エルフの森の女の子", "花澤香菜", 6, 6, "アオイ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 6, "カルミナ", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 163, 17, 104201, "O", "各種楽器", 46, "人々を守るために歌う、唱喚士の少女", "福原綾香", 4, 3, "チカ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 8, "自警団（カォン）", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 168, 17, 104301, "O", "お菓子作り", 54, "男勝りで情に厚いワイルド娘", "小松未可子", 10, 9, "マコト");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 5, "悪魔偽王国軍（ディアボロス）", "test", 172, "??", 104401, "A", "世界征服", 50, "かつては夜を支配した最強の吸血鬼", "丹下桜", 7, 5, "イリヤ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 11, "ヴァイスフリューゲル　ランドソル支部", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 157, 18, 104501, "AB", "小説を読むこと", 49, "妄想大好き！　ほんとは照れ屋な女の子", "長妻樹里", 15, 19, "クウカ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 3, "メルクリウス財団", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 158, 19, 104601, "AB", "猫とたわむれること", 48, "弱きを助け強きをくじく猫娘", "沼倉愛美", 12, 1, "タマキ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 10, "王宮騎士団（NIGHTMARE）", "？？？", 171, 25, 104701, "A", "格闘技、湯浴み", 50, "素顔を見せない冷静沈着な女性騎士", "川澄綾子", 8, 25, "ジュン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 11, "メルクリウス財団", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 163, 20, 104801, "O", "傭兵などのアルバイト", 49, "仕事も私事も効率優先な傭兵少女", "田所あずさ", 12, 11, "ミフユ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 10, "ラビリンス", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 168, 18, 104901, "O", "家事全般", 54, "お姉ちゃんがお世話してあげるからねっ！", "生天目仁美", 3, 24, "シズル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 1, "ルーセント学院", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 120, 11, 105001, "A", "ファッション誌鑑賞、コスメ集め", 22, "ちょっとおませな恋に恋する女の子", "久野美咲", 14, 3, "ミサキ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 3, "トワイライトキャラバン", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 166, 27, 105101, "A", "研究、実験", 53, "実験が趣味の危険な科学者", "三石琴乃", 13, 7, "ミツキ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 3, "牧場（エリザベスパーク）", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", 150, 17, 105201, "A", "毛繕い、お喋り", 100, "乙女チックなもふもふアニマル", "徳井青空", 11, 14, "リマ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 7, "ヴァイスフリューゲル　ランドソル支部", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 140, 17, 105301, "A", "お菓子屋通い", 33, "見た目も中身もお子ちゃまな異国の軍人", "辻あゆみ", 15, 28, "モニカ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 9, "カルミナ", "test", 153, 14, 105401, "AB", "裁縫", 45, "ファッション大好きなキュートガール", "木戸衣吹", 4, 7, "ツムギ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 4, "ヴァイスフリューゲル　ランドソル支部", "test", 155, 16, 105501, "O", "観察", 43, "どこまでも一途に慕う、純情乙女", "大関英里", 15, 7, "アユミ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 7, "トワイライトキャラバン", "test", 167, 25, 105601, "B", "釣り", 54, "人情味溢れる粋でいなせな「姉御」", "佐藤利奈", 13, 11, "ルカ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 3, "？？？", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", 156, 17, 105701, "O", "冒険、おしゃべり", 45, "空への冒険を夢見る騎空士の少女", "金元寿子", "", 10, "ジータ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 3, "美食殿", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 156, 17, 105801, "O", "食べ歩き、料理", 46, "いつも元気な腹ペコ少女", "M・A・O", 1, 31, "ペコリーヌ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 5, "美食殿", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 140, 11, 105901, "B", "瞑想、動植物の飼育", 35, "主を慕う、小さなガイド役", "伊藤美来", 1, 11, "コッコロ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 9, "美食殿", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 152, 14, 106001, "A", "猫と遊ぶ", 39, "行き倒れの謎のネコミミ魔法使い", "立花理香", 1, 2, "キャル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 8, "？？？", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", 148, 16, 106101, "O", "冒険、思い出話", 40, "さまよえる謎の少女", "潘めぐみ", "", 11, "ムイミ");
