INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 9, "美食殿", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 152, 14, 107801, "A", "猫と遊ぶ", 39, "行き倒れの謎のネコミミ魔法使い", "立花理香", 1, 2, "キャル（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 3, "メルクリウス財団", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 158, 19, 107901, "AB", "猫とたわむれること", 48, "弱きを助け強きをくじく猫娘", "沼倉愛美", 12, 1, "タマキ（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 11, "メルクリウス財団", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 163, 20, 108001, "O", "傭兵などのアルバイト", 49, "仕事も私事も効率優先な傭兵少女", "田所あずさ", 12, 11, "ミフユ（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 12, "悪魔偽王国軍（ディアボロス）", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 157, 18, 108101, "AB", "占い", 42, "占いが得意な霊能少女", "大坪由佳", 7, 22, "シノブ（ハロウィン）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 1, "悪魔偽王国軍（ディアボロス）", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 130, 14, 108201, "B", "プリンを食べること", 32, "プリン大好きゴースト娘", "雨宮天", 7, 23, "ミヤコ（ハロウィン）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 1, "ルーセント学院", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 120, 11, 108301, "A", "ファッション誌鑑賞、コスメ集め", 22, "ちょっとおませな恋に恋する女の子", "久野美咲", 14, 3, "ミサキ（ハロウィン）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 6, "カルミナ", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 163, 17, 108401, "O", "各種楽器", 46, "人々を守るために歌う、唱喚士の少女", "福原綾香", 4, 3, "チカ（クリスマス）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 6, "サレンディア救護院", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 150, 12, 108501, "B", "観劇、おままごと", 40, "泣き虫で臆病な守ってあげたい女の子", "植田佳奈", 9, 9, "クルミ（クリスマス）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 5, "サレンディア救護院", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 148, 14, 108601, "B", "屋内でできる遊び", 38, "ぷうきちといつも一緒！", "芹澤優", 9, 10, "アヤネ（クリスマス）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 8, "トゥインクルウィッシュ", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 155, 16, 108701, "A", "人助け、応援", 44, "人助けが大好き！　前向き格闘娘", "東山奈央", 2, 27, "ヒヨリ（ニューイヤー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 4, "トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 158, 17, 108801, "O", "料理、人間観察", 47, "戦闘のサポートが得意な、心優しい少女", "種田梨沙", 2, 5, "ユイ（ニューイヤー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 1, "トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 163, 18, 108901, "B", "読書、乗馬、お茶", 46, "クールで何事にも真っ直ぐな剣士", "早見沙織", 2, 12, "レイ（ニューイヤー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 7, "トワイライトキャラバン", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 154, 16, 109001, "B", "実験、裁縫、料理", 43, "運命の相手に一途すぎる乙女", "橋本ちなみ", 13, 30, "エリコ（バレンタイン）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 10, "ラビリンス", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 168, 18, 109101, "O", "家事全般", 54, "お姉ちゃんがお世話してあげるからねっ！", "生天目仁美", 3, 24, "シズル（バレンタイン）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 12, "？？？", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", 156, 17, 109201, "AB", "読書", 55, "英霊と契約を結んだマナリアの天才王女", "日笠陽子", "", 1, "アン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 2, "？？？", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", 144, 16, 109301, "O", "食べること、眠ること", 45, "マナリア魔法学院の新入生", "こやまきみこ", "", 4, "ルゥ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("半人半竜", 0, 11, "？？？", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", 167, 17, 109401, "B", "ピアノ", 67, "人を超越した力を有す心優しい竜姫", "福原綾香", "", 3, "グレア");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 11, "ヴァイスフリューゲル　ランドソル支部", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 157, 18, 109501, "AB", "小説を読むこと", 49, "妄想大好き！　ほんとは照れ屋な女の子", "長妻樹里", 15, 19, "クウカ（オーエド）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 8, "ヴァイスフリューゲル　ランドソル支部", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 163, 16, 109601, "O", "忍法開発", 51, "トーゴクの神秘、オシエテクダサイ！", "佐藤聡美", 15, 31, "ニノン（オーエド）");
