INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 10, "王宮騎士団（NIGHTMARE）", "", 171, 25, 113601, "A", "格闘技、湯浴み", 50, "素顔を見せない冷静沈着な女性騎士", "川澄綾子", 8, 25, "ジュン（サマー）");
