INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 11, "悪魔偽王国軍（ディアボロス）", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 150, 13, 113801, "O", "ゲーム全般", 40, "人見知りであまのじゃくな女の子", "原紗友里", 7, 22, "ヨリ（エンジェル）");
