INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 9, "自警団（カォン）", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 155, 16, 116001, "O", "空想、ぬいぐるみ集め", 42, "マホマホ王国のプリンセス", "内田真礼", 10, 22, "マホ（シンデレラ）");
