INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 3, "メルクリウス財団", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 158, 19, 116801, "AB", "猫とたわむれること", 48, "弱きを助け強きをくじく猫娘", "沼倉愛美", 12, 1, "タマキ（作業服）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 11, "メルクリウス財団", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 163, 20, 116901, "O", "傭兵などのアルバイト", 49, "仕事も私事も効率優先な傭兵少女", "田所あずさ", 12, 11, "ミフユ（作業服）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 7, "トワイライトキャラバン", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 154, 16, 117001, "B", "実験、裁縫、料理", 43, "運命の相手に一途すぎる乙女", "橋本ちなみ", 13, 30, "エリコ（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 10, "ラビリンス", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 168, 18, 117101, "O", "家事全般", 54, "お姉ちゃんがお世話してあげるからねっ！", "生天目仁美", 3, 24, "シズル（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 1, "カルミナ", "", 157, 17, 117201, "B", "舞台鑑賞、ダンス", 40, "歌って踊れる大人気アイドル", "日笠陽子", 4, 24, "ノゾミ（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 6, "カルミナ", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 163, 17, 117301, "O", "各種楽器", 46, "人々を守るために歌う、唱喚士の少女", "福原綾香", 4, 3, "チカ（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 9, "カルミナ", "", 153, 14, 117401, "AB", "裁縫", 45, "ファッション大好きなキュートガール", "木戸衣吹", 4, 7, "ツムギ（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 3, "トワイライトキャラバン", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 166, 27, 117501, "A", "研究、実験", 53, "実験が趣味の危険な科学者", "三石琴乃", 13, 7, "ミツキ（オーエド）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 10, "ヴァイスフリューゲル　ランドソル支部", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 150, 14, 117601, "AB", "鏡で自分を見ること", 40, "ボクは誰よりも美しい", "大空直美", 15, 10, "ユキ（オーエド）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 7, "自警団（カォン）", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 158, 17, 117701, "A", "踊り、空手", 53, "いつでも「なんくるないさ～」な天然娘", "高森奈津美", 10, 7, "カオリ（ハロウィン）");
