INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 8, "ルーセント学院", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 162, 23, 119001, "B", "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 52, "多くの男性を魅了する無垢な女教師", "伊藤静", 14, 14, "イオ（ノワール）");
