INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 7, "ラビリンス", "", 160, 25, 121201, "AB", "人間観察", "??", "秘密結社ラビリンスの『迷宮女王』", "沢城みゆき", 3, 25, "ラビリスタ（オーバーロード）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 6, "サレンディア救護院", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 150, 12, 121301, "B", "観劇、おままごと", 40, "泣き虫で臆病な守ってあげたい女の子", "植田佳奈", 9, 9, "クルミ（ステージ）");
