INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ドラゴン族", 0, 9, "ドラゴンズネスト", "", 145, 13, 121601, "AB", "ゲーム", "???", "口が達者なヘタレドラゴン", "藤田茜", 17, 29, "イノリ（怪盗）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 7, "トワイライトキャラバン", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 159, 17, 121901, "A", "小説執筆", 45, "前世を信じる中二病患者、「疾風の冥姫」", "髙野麻美", 13, 5, "アンナ（パイレーツ）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 12, "悪魔偽王国軍（ディアボロス）", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 157, 18, 122001, "AB", "占い", 42, "占いが得意な霊能少女", "大坪由佳", 7, 22, "シノブ（パイレーツ）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 6, "フォレスティエ", "", 158, 13, 122101, "AB", "友達作りのイメトレ", 44, "「友達」に憧れる、エルフの森の女の子", "花澤香菜", 6, 6, "アオイ（キャンプ）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 3, "メルクリウス財団", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 164, 22, 122201, "A", "ウインドーショッピング", 55, "純情でほっとけない大人の女性", "今井麻美", 12, 16, "ユカリ（キャンプ）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 12, "？？？", "", 149, "??", 122301, "AB", "お散歩、お料理", 41, "けんぞくのご主人様", "釘宮理恵", "", 6, "ヴァンピィ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 8, "トゥインクルウィッシュ", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 155, 16, 122401, "A", "人助け、応援", 44, "人助けが大好き！　前向き格闘娘", "東山奈央", 2, 27, "ヒヨリ（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("魔族", 0, 1, "トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 163, 18, 122501, "B", "読書、乗馬、お茶", 46, "クールで何事にも真っ直ぐな剣士", "早見沙織", 2, 12, "レイ（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 4, "トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 158, 17, 122601, "O", "料理、人間観察", 47, "戦闘のサポートが得意な、心優しい少女", "種田梨沙", 2, 5, "ユイ（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("エルフ", 0, 2, "リトルリリカル", "", 118, 8, 122701, "A", "お勉強", 21, "礼儀正しくしっかり者のちびっ子優等生", "小倉唯", 5, 2, "キョウカ（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 8, "リトルリリカル", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 128, 9, 122801, "O", "いたずら、探検", 27, "探検好きのイタズラっ子", "諸星すみれ", 5, 10, "ミソギ（サマー）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("獣人族", 0, 4, "リトルリリカル", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 117, 10, 122901, "O", "かわいいもの集め", 21, "お歌もにんじんも、ウサギさんも大好き♪", "日高里菜", 5, 3, "ミミ（サマー）");
