INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒューマン", 0, 7, "ヴァイスフリューゲル　ランドソル支部", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 140, 17, 125201, "A", "お菓子屋通い", 33, "見た目も中身もお子ちゃまな異国の軍人", "辻あゆみ", 15, 28, "モニカ（カフェ）");
